package stream

import (
	"encoding/json"
	"testing"
)

// TestPackGate is the acceptance test for the pack gate (playback-capability-
// gate "Opt-in gate on the pack lane", D1): PackGate is the single judge whose
// open verdict is exactly today's packable predicate (Classify ∈ {pack,
// opt_in-with-knob}) and whose refusals are exactly the state_reason tokens —
// codec_not_opted_in for opt-in codecs with the knob off, codec_unsupported
// for everything the pack lane cannot serve. Every case also pins the
// equivalence to the predicate it replaces, so the judge cannot drift from
// either side.
func TestPackGate(t *testing.T) {
	cases := []struct {
		name    string
		ffprobe string // synthetic verbatim ffprobe JSON
		optIn   bool   // the opt-in codec knob
		want    Gate
	}{
		// Pack-class codecs open regardless of the knob: the container is the
		// only obstacle.
		{name: "mkv_h264_aac_opens_knob_off", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, want: GateOpen},
		{name: "mkv_h264_aac_opens_knob_on", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: GateOpen},
		{name: "avi_h264_mp3_opens", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"mp3"}],"format":{"format_name":"avi"}}`, want: GateOpen},

		// Opt-in codecs name the knob when it is the unmet gate.
		{name: "mkv_hevc_knob_off_refuses_not_opted_in", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"hevc","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, want: Gate(ReasonCodecNotOptedIn)},
		{name: "mkv_hevc_knob_on_opens", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"hevc","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: GateOpen},
		{name: "mkv_ac3_audio_knob_off_refuses_not_opted_in", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"ac3"}],"format":{"format_name":"matroska,webm"}}`, want: Gate(ReasonCodecNotOptedIn)},
		{name: "mkv_eac3_sidecar_knob_on_opens", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"},{"codec_type":"audio","codec_name":"eac3"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: GateOpen},

		// Genuinely unremuxable codecs refuse unsupported — never the knob
		// token, whatever the knob reads.
		{name: "mkv_h264_10bit_refuses_unsupported", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: Gate(ReasonCodecUnsupported)},
		{name: "mkv_dts_audio_refuses_unsupported", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"dts"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: Gate(ReasonCodecUnsupported)},
		{name: "unknown_video_codec_refuses_unsupported", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"mpeg2video","pix_fmt":"yuv420p"}],"format":{"format_name":"mov,mp4,m4a,3gp,3g2,mj2"}}`, optIn: true, want: Gate(ReasonCodecUnsupported)},

		// Fail-safe negatives (INV2): degraded facts never open the gate.
		{name: "empty_facts_refuse_unsupported", ffprobe: `{}`, optIn: true, want: Gate(ReasonCodecUnsupported)},
		{name: "nil_facts_refuse_unsupported", ffprobe: "", want: Gate(ReasonCodecUnsupported)},
		{name: "audio_only_refuses_unsupported", ffprobe: `{"streams":[{"codec_type":"audio","codec_name":"mp3"}],"format":{"format_name":"mp3"}}`, want: Gate(ReasonCodecUnsupported)},

		// The direct class (native container, decodable codecs) closes too —
		// the pack lane has nothing to remux into service for it.
		{name: "native_mp4_closes_unsupported", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"mov,mp4,m4a,3gp,3g2,mj2"}}`, optIn: true, want: Gate(ReasonCodecUnsupported)},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			var facts map[string]any
			if tc.ffprobe != "" {
				if err := json.Unmarshal([]byte(tc.ffprobe), &facts); err != nil {
					t.Fatalf("unmarshal ffprobe fixture: %v", err)
				}
			}
			got := PackGate(facts, tc.optIn)
			if got != tc.want {
				t.Errorf("PackGate = %q, want %q", got, tc.want)
			}
			// The equivalence pin (D1): GateOpen ⇔ today's packable predicate.
			packable := false
			switch Classify(facts, tc.optIn) {
			case ClassPack, ClassOptIn:
				packable = true
			}
			if (got == GateOpen) != packable {
				t.Errorf("PackGate = %q disagrees with the packable predicate (Classify = packable: %v)", got, packable)
			}
		})
	}

	t.Run("refusals_are_the_state_reason_tokens", func(t *testing.T) {
		// One vocabulary (D1): the gate's refusals ARE the descriptor's
		// state_reason tokens, byte for byte.
		if string(Gate(ReasonCodecNotOptedIn)) != "codec_not_opted_in" {
			t.Errorf("not-opted-in token = %q, want codec_not_opted_in", ReasonCodecNotOptedIn)
		}
		if string(Gate(ReasonCodecUnsupported)) != "codec_unsupported" {
			t.Errorf("unsupported token = %q, want codec_unsupported", ReasonCodecUnsupported)
		}
	})

	t.Run("pure_input", func(t *testing.T) {
		// The same purity contract Classify carries (INV1): the stored
		// document map is shared with every other reader.
		var facts map[string]any
		if err := json.Unmarshal([]byte(`{"streams":[{"codec_type":"video","codec_name":"hevc","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"ac3"}],"format":{"format_name":"matroska,webm"}}`), &facts); err != nil {
			t.Fatalf("unmarshal: %v", err)
		}
		before, _ := json.Marshal(facts)
		PackGate(facts, false)
		PackGate(facts, true)
		after, _ := json.Marshal(facts)
		if string(after) != string(before) {
			t.Errorf("PackGate mutated its input: before=%s after=%s", before, after)
		}
	})
}
